-- 0001 – PostgreSQL port of the legacy SQLite schema (market_unified.db).
-- One table per legacy table, same names, same columns, same keys.
-- Type mapping (see .docs/DATABASE_MIGRATION.md):
--   INTEGER PRIMARY KEY AUTOINCREMENT -> integer GENERATED BY DEFAULT AS IDENTITY (explicit ids allowed for the import)
--   REAL (money, quantities)          -> numeric (unconstrained: legacy doubles are stored exactly, no rounding)
--   TEXT local date-times             -> timestamp without time zone (store-local wall-clock time, as before)
--   TEXT dates (cheques)              -> date
-- Legacy foreign keys are kept. Triggers are ported 1:1 with the same Arabic messages.

CREATE TABLE users (
  id            integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  username      text NOT NULL UNIQUE,
  password_hash text,                      -- legacy PIN (SHA-256 hex or plain text); cleared after upgrade
  role          text NOT NULL DEFAULT 'cashier'
);

CREATE TABLE products (
  barcode         text PRIMARY KEY,
  name            text NOT NULL,
  cost_price      numeric DEFAULT 0,
  retail_price    numeric DEFAULT 0,
  wholesale_price numeric DEFAULT 0,
  stock_qty       numeric DEFAULT 0,
  reorder_limit   numeric DEFAULT 0,
  unit            text,
  category        text
);

CREATE TABLE clients (
  id           integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name         text NOT NULL,
  phone        text UNIQUE,
  address      text,
  debt_balance numeric DEFAULT 0,
  points       integer DEFAULT 0,
  created_at   timestamp
);

CREATE TABLE client_ledger (
  id          integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  client_id   integer REFERENCES clients(id),
  type        text,
  amount      numeric,
  description text,
  timestamp   timestamp
);

CREATE TABLE shifts (
  id                   integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id              integer NOT NULL REFERENCES users(id),
  start_time           timestamp,
  end_time             timestamp,
  initial_cash         numeric DEFAULT 0,
  expected_end_cash    numeric DEFAULT 0,
  actual_end_cash      numeric DEFAULT 0,
  difference           numeric,
  status               text DEFAULT 'open',
  momkn_start_balance  numeric DEFAULT 0,
  momkn_start_cash     numeric DEFAULT 0,
  vfcash_start_balance numeric DEFAULT 0,
  vfcash_start_cash    numeric DEFAULT 0
);

CREATE TABLE sales (
  id              integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  shift_id        integer REFERENCES shifts(id),
  user_id         integer,
  timestamp       timestamp,
  total_amount    numeric DEFAULT 0,
  original_amount numeric DEFAULT 0,
  discount        numeric DEFAULT 0,
  payment_type    text,
  client_name     text,
  client_id       integer REFERENCES clients(id)
);

CREATE TABLE sale_items (
  id              integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  sale_id         integer NOT NULL REFERENCES sales(id) ON DELETE CASCADE,
  product_barcode text REFERENCES products(barcode),
  quantity        numeric NOT NULL,
  unit_price      numeric NOT NULL,
  total_price     numeric NOT NULL,
  cost_price      numeric DEFAULT 0,
  returned_qty    numeric DEFAULT 0
);

CREATE TABLE suppliers (
  id             integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name           text NOT NULL,
  phone          text,
  address        text,
  contact_person text,
  debt_balance   numeric DEFAULT 0,
  created_at     timestamp
);

CREATE TABLE supplier_ledger (
  id          integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  supplier_id integer NOT NULL REFERENCES suppliers(id),
  type        text NOT NULL,
  amount      numeric NOT NULL,
  description text,
  timestamp   timestamp
);

CREATE TABLE supplier_purchases (
  id           integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  supplier_id  integer NOT NULL REFERENCES suppliers(id),
  invoice_ref  text,
  total_amount numeric NOT NULL,
  paid_amount  numeric DEFAULT 0,
  remaining    numeric DEFAULT 0,
  payment_type text DEFAULT 'آجل',
  timestamp    timestamp,
  notes        text
);

CREATE TABLE checks_register (
  id           integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  check_type   text NOT NULL,
  check_number text,
  bank_name    text,
  party_name   text NOT NULL,
  issue_date   date,
  due_date     date NOT NULL,
  amount       numeric NOT NULL,
  status       text DEFAULT 'غير مسدد',
  notes        text,
  created_at   timestamp
);

CREATE TABLE expenses (
  id          integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  shift_id    integer,
  amount      numeric NOT NULL,
  category    text,
  description text,
  timestamp   timestamp
);

CREATE TABLE damaged_goods (
  id              integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  shift_id        integer,
  product_barcode text NOT NULL REFERENCES products(barcode),
  quantity        numeric NOT NULL,
  reason          text,
  cost_price      numeric NOT NULL,
  timestamp       timestamp
);

CREATE TABLE settings (
  key   text PRIMARY KEY,
  value text
);

CREATE TABLE shift_audits (
  id            integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  shift_id      integer REFERENCES shifts(id),
  timestamp     timestamp NOT NULL,
  expected_cash numeric NOT NULL,
  actual_cash   numeric NOT NULL,
  difference    numeric NOT NULL,
  notes         text
);

CREATE TABLE system_logs (
  id          integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  timestamp   timestamp NOT NULL,
  user_id     integer,
  username    text,
  action_type text NOT NULL,
  description text,
  details     text
);

CREATE TABLE momkn_transactions (
  id             integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  shift_id       integer NOT NULL REFERENCES shifts(id),
  timestamp      timestamp NOT NULL,
  operation_type text NOT NULL,
  description    text,
  digital_impact numeric NOT NULL,
  cash_impact    numeric NOT NULL,
  commission     numeric DEFAULT 0,
  notes          text
);

CREATE TABLE mobile_money_transactions (
  id               integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  shift_id         integer NOT NULL REFERENCES shifts(id),
  timestamp        timestamp NOT NULL,
  platform         text NOT NULL,
  operation_type   text NOT NULL,
  digital_impact   numeric NOT NULL,
  cash_impact      numeric NOT NULL,
  commission       numeric DEFAULT 0,
  recipient_name   text,
  phone_or_account text,
  notes            text
);

CREATE TABLE safe_ledger (
  id          integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  shift_id    integer NOT NULL REFERENCES shifts(id),
  type        text NOT NULL,
  amount      numeric NOT NULL,
  description text,
  timestamp   timestamp NOT NULL
);

CREATE INDEX idx_sales_shift_id ON sales(shift_id);
CREATE INDEX idx_sales_client_id ON sales(client_id);
CREATE INDEX idx_sale_items_sale_id ON sale_items(sale_id);
CREATE INDEX idx_sale_items_barcode ON sale_items(product_barcode);
CREATE INDEX idx_safe_ledger_shift_id ON safe_ledger(shift_id);
CREATE INDEX idx_client_ledger_client_id ON client_ledger(client_id);
CREATE INDEX idx_supplier_ledger_supplier_id ON supplier_ledger(supplier_id);
-- New, for date-range reports (no semantic change)
CREATE INDEX idx_sales_timestamp ON sales(timestamp);
CREATE INDEX idx_system_logs_timestamp ON system_logs(timestamp);

-- Triggers: same conditions and messages as the SQLite triggers.
CREATE FUNCTION hm_prevent_negative_stock() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.stock_qty < 0 THEN
    RAISE EXCEPTION 'خطأ: لا يمكن أن تقل كمية المخزون عن صفر (نفاد الكمية).' USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER prevent_negative_stock BEFORE UPDATE OF stock_qty ON products
  FOR EACH ROW EXECUTE FUNCTION hm_prevent_negative_stock();

CREATE FUNCTION hm_prevent_sale_on_closed_shift() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF (SELECT status FROM shifts WHERE id = NEW.shift_id) = 'closed' THEN
    RAISE EXCEPTION 'خطأ: لا يمكن تسجيل عملية بيع على وردية مغلقة.' USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER prevent_sale_on_closed_shift BEFORE INSERT ON sales
  FOR EACH ROW EXECUTE FUNCTION hm_prevent_sale_on_closed_shift();

CREATE FUNCTION hm_prevent_multiple_open_shifts() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.status = 'open' AND (SELECT COUNT(*) FROM shifts WHERE user_id = NEW.user_id AND status = 'open') > 0 THEN
    RAISE EXCEPTION 'خطأ: يوجد وردية مفتوحة بالفعل لهذا المستخدم.' USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER prevent_multiple_open_shifts BEFORE INSERT ON shifts
  FOR EACH ROW EXECUTE FUNCTION hm_prevent_multiple_open_shifts();
